#!/bin/bash
# Revision-pass re-measures (2026-09-05). Store read-only throughout.
DB='file:/home/hoang/nofx/data/data.db?mode=ro'
echo "== compliant era population =="
sqlite3 "$DB" "SELECT COUNT(*), ROUND(SUM(pnl_corrected),2), ROUND(AVG(pnl_corrected),4) FROM trader_positions WHERE entry_time>=strftime('%s','2026-08-15 05:00:00')*1000 AND source<>'e7_farside_test' AND pnl_corrected IS NOT NULL AND plan_id<>'UNRESOLVABLE';"
echo "== the 7 UNRESOLVABLE era rows excluded =="
sqlite3 "$DB" "SELECT id,source,pnl_corrected FROM trader_positions WHERE entry_time>=strftime('%s','2026-08-15 05:00:00')*1000 AND plan_id='UNRESOLVABLE' AND source<>'e7_farside_test' ORDER BY id;"
echo "== armed_orders ids 5-37: 33 rows, 2 TEST-E7 seams (15,16) =="
sqlite3 "$DB" "SELECT COUNT(*), SUM(session='TEST-E7'), SUM(state_reason LIKE 'level accepted through%'), SUM(state='filled' AND session<>'TEST-E7') FROM armed_orders WHERE id BETWEEN 5 AND 37;"
echo "== 09-04 arms by state/reason (superseded ids are EVEN) =="
sqlite3 "$DB" "SELECT state, substr(state_reason,1,34), COUNT(*), group_concat(id) FROM armed_orders WHERE id>=38 GROUP BY 1,2;"
echo "== wait buckets 37078-37169 =="
for r in "37078 37090" "37091 37098" "37099 37123" "37124 37141" "37142 37169"; do set -- $r
  sqlite3 "$DB" "SELECT '$1-$2 n='||COUNT(*)||' wait='||SUM(decision_json LIKE '%\"action\": \"wait\"%') FROM decision_records WHERE id BETWEEN $1 AND $2;"; done
echo "== ab_confirm_log net_pnl, BOTH clocks =="
sqlite3 "$DB" "SELECT 'created_ct '||date(strftime('%s',created_at),'unixepoch','-5 hours'), COUNT(*), ROUND(SUM(net_pnl),2) FROM ab_confirm_log GROUP BY 1;"
sqlite3 "$DB" "SELECT 'plan_td '||substr(plan_id,1,10), COUNT(*), ROUND(SUM(net_pnl),2) FROM ab_confirm_log GROUP BY 1;"
sqlite3 "$DB" "SELECT id, created_at, version, ROUND(net_pnl,2) FROM ab_confirm_log WHERE id IN (169,171);"
echo "== nt8_order_snapshots: still growing on 09-05 =="
sqlite3 "$DB" "SELECT COUNT(*), SUM(emitted_at_ms<=strftime('%s','2026-09-05 14:56:00')*1000), datetime(MAX(emitted_at_ms)/1000,'unixepoch','-5 hours'), SUM(date(emitted_at_ms/1000,'unixepoch','-5 hours')='2026-09-03'), SUM(date(emitted_at_ms/1000,'unixepoch','-5 hours')='2026-09-04') FROM nt8_order_snapshots;"
echo "== snapshot working_count ladder around the peak =="
sqlite3 "$DB" "SELECT id, datetime(emitted_at_ms/1000,'unixepoch','-5 hours'), working_count FROM nt8_order_snapshots WHERE id BETWEEN 1604 AND 1615;"
echo "== 09-04 hourly (the 07:00 hour is -135.75 open-to-close, 218 range) =="
sqlite3 "$DB" "WITH b AS (SELECT open_time_ms,o,h,l,c,datetime(open_time_ms/1000,'unixepoch','-5 hours') ct FROM bars WHERE symbol='MNQ' AND tf='1m' AND date(open_time_ms/1000,'unixepoch','-5 hours')='2026-09-04') SELECT substr(ct,12,2), (SELECT o FROM b x WHERE substr(x.ct,12,2)=substr(b.ct,12,2) ORDER BY x.open_time_ms LIMIT 1), MAX(h), MIN(l), (SELECT c FROM b x WHERE substr(x.ct,12,2)=substr(b.ct,12,2) ORDER BY x.open_time_ms DESC LIMIT 1) FROM b WHERE substr(ct,12,2) IN ('07','08','09','10','11') GROUP BY 1;"
echo "== 09-03 NY v3-v7 scenarios: 10 longs, not 11 =="
sqlite3 "$DB" "SELECT p.version, json_extract(s.value,'\$.id'), json_extract(s.value,'\$.direction'), json_extract(s.value,'\$.condition') FROM plans p, json_each(json_extract(p.doc,'\$.scenarios')) s WHERE p.trade_date='2026-09-03' AND p.session='NY' AND p.version BETWEEN 3 AND 7 ORDER BY p.version;"
echo "== breakup_continue has NEVER been authored (0 of 254 plans) =="
sqlite3 "$DB" "SELECT json_extract(s.value,'\$.condition'), COUNT(*) FROM plans p, json_each(json_extract(p.doc,'\$.scenarios')) s GROUP BY 1 ORDER BY 2 DESC;"
echo "== position 591: broker stop == fill; the 3.37 'slip' is ledger drift =="
sqlite3 "$DB" "SELECT id, exit_price FROM trader_positions WHERE id=591;"
sqlite3 "$DB" "SELECT id, stop_px, updated_at FROM armed_orders WHERE id=35;"
echo "  NT8 log 09-03 09:02:54 submitted entry ... (SL=29355 TP=29144.5 on fill)"
echo "  NT8 log 09-03 09:03:53 Name='...-sl' Limit price=0 Stop price=29355 Type='Stop Market'"
echo "== 09-03 empty-book window: 09:20 close -> 11:58 close/high =="
sqlite3 "$DB" "SELECT datetime(open_time_ms/1000,'unixepoch','-5 hours'), o,h,l,c FROM bars WHERE symbol='MNQ' AND tf='1m' AND datetime(open_time_ms/1000,'unixepoch','-5 hours') IN ('2026-09-03 09:20:00','2026-09-03 09:59:00','2026-09-03 11:58:00');"
sqlite3 "$DB" "SELECT MAX(h), MIN(l) FROM bars WHERE symbol='MNQ' AND tf='1m' AND datetime(open_time_ms/1000,'unixepoch','-5 hours') BETWEEN '2026-09-03 09:20:00' AND '2026-09-03 11:58:00';"
echo "== IB high 08:30-09:29 09-03 =="
sqlite3 "$DB" "SELECT MAX(h), MIN(l) FROM bars WHERE symbol='MNQ' AND tf='1m' AND datetime(open_time_ms/1000,'unixepoch','-5 hours') BETWEEN '2026-09-03 08:30:00' AND '2026-09-03 09:29:00';"
echo "== WSL2 drifting clocks (read again during the revision) =="
echo "  uptime -s / /proc/stat btime slide with no reboot; systemctl is the stable record."
